"""Unit DTOs only, generated by the unchanged frozen Python decision service.

No DB, model execution or business data. The reader supplies the existing marked
SYNTHETIC curve. Real HTTPS/PostgreSQL acceptance is executed separately.
"""

import asyncio
import json
from pathlib import Path

from backend.app.forecast_intelligence.decision_service import DecisionSupportService
from backend.app.forecast_intelligence.read_schemas import CurveData, ReadResponse

HERE = Path(__file__).resolve().parent


async def main():
    fixture = json.loads((HERE / "dashboard-synthetic.json").read_bytes())

    class Reader:
        async def curve(self, query):
            return ReadResponse[CurveData].model_validate(fixture["reads"]["curve"])

    service = DecisionSupportService(Reader())
    request = fixture["simulation_request"]
    request["scenario_id"] = "SYNTHETIC_WORKFORCE"
    request["capacity_rows"] = [
        {
            "date": r["date"],
            "capacity_mode": "WORKFORCE_DERIVED",
            "workforce_count": 10,
            "productivity_kg_per_person_day": "14",
            "buffer_handling_capacity_kg": "0",
        }
        for r in request["capacity_rows"]
    ]
    comparison = fixture["comparison_request"]
    comparison["scenarios"][1] = {
        k: request[k] for k in ("scenario_id", "scenario_version", "capacity_rows")
    }
    value = {
        "SYNTHETIC": True,
        "simulation_request": request,
        "simulation": (await service.simulate(request)).model_dump(mode="json"),
        "comparison_request": comparison,
        "comparison": (await service.compare(comparison)).model_dump(mode="json"),
    }
    (HERE / "option-b-workforce-synthetic.json").write_text(
        json.dumps(value, sort_keys=True, indent=2, ensure_ascii=False) + "\n"
    )


if __name__ == "__main__":
    asyncio.run(main())
